INSERT INTO `blocks` VALUES (1,'Welcome Message','welcome-message','A welcoming introduction for visitors','Welcome to our website! We are dedicated to providing you with the best experience possible. Our team works tirelessly to bring you quality content, innovative solutions, and exceptional service. Whether you are a first-time visitor or a returning customer, we are thrilled to have you here.','published',NULL,'2026-10-01 06:33:22','2026-10-01 06:33:22',NULL),(2,'About Us Summary','about-us-summary','Brief company overview and mission statement','Founded with a passion for excellence, our company has grown to become a trusted name in the industry. We believe in delivering value through innovation, integrity, and dedication. Our mission is to empower our customers with solutions that make a difference in their lives.','published',NULL,'2026-10-01 06:33:22','2026-10-01 06:33:22',NULL),(3,'Newsletter Signup','newsletter-signup','Call to action for newsletter subscription','Stay updated with our latest news, offers, and insights! Subscribe to our newsletter and be the first to know about exciting developments. Join our community of subscribers who receive exclusive content directly in their inbox.','published',NULL,'2026-10-01 06:33:22','2026-10-01 06:33:22',NULL),(4,'Contact Information','contact-information','Company contact details and support info','Have questions or need assistance? Our support team is here to help. Reach out to us via email at support@example.com or call us at +1 (555) 123-4567. Our office hours are Monday through Friday, 9 AM to 6 PM EST.','published',NULL,'2026-10-01 06:33:22','2026-10-01 06:33:22',NULL),(5,'Featured Promotion','featured-promotion','Current promotional content and special offers','Do not miss out on our exclusive offers! For a limited time, enjoy special discounts on selected products and services. Take advantage of these amazing deals and discover why our customers keep coming back for more.','published',NULL,'2026-10-01 06:33:22','2026-10-01 06:33:22',NULL);
