INSERT INTO `galleries` VALUES (1,'Tech Conference 2024','Annual technology conference featuring keynote speakers, workshops, and networking opportunities for industry professionals.',1,0,'news/6.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(2,'Product Launch Event','Exclusive unveiling of our latest product line with live demonstrations and Q&amp;A sessions with the development team.',1,0,'news/7.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(3,'Team Building Retreat','Company-wide retreat focused on collaboration, innovation, and strengthening team bonds in a relaxed environment.',1,0,'news/8.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(4,'Innovation Summit','Two-day summit bringing together thought leaders to discuss emerging technologies and future trends.',1,0,'news/9.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(5,'Developer Meetup','Monthly gathering of developers to share knowledge, discuss best practices, and collaborate on open-source projects.',1,0,'news/10.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(6,'AI Workshop Series','Hands-on workshops covering machine learning, neural networks, and practical AI applications.',1,0,'news/11.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(7,'Startup Showcase','Platform for emerging startups to present their innovative solutions to investors and industry experts.',0,0,'news/12.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(8,'Company Anniversary','Celebrating our journey with employees, partners, and customers who made our success possible.',0,0,'news/13.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(9,'Hackathon Weekend','48-hour coding marathon where teams compete to build innovative solutions to real-world problems.',0,0,'news/14.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(10,'Industry Awards Night','Annual ceremony recognizing excellence and innovation in technology across various categories.',0,0,'news/15.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(11,'New Office Opening','Grand opening of our state-of-the-art facility designed to foster creativity and collaboration.',0,0,'news/16.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(12,'Community Outreach','Initiatives focused on giving back to the community through education and technology access programs.',0,0,'news/17.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(13,'Tech Talks Series','Weekly presentations by industry experts covering cutting-edge technologies and best practices.',0,0,'news/18.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(14,'Partnership Celebration','Commemorating strategic partnerships that drive innovation and mutual growth.',0,0,'news/19.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15'),(15,'Year in Review','Annual retrospective highlighting achievements, milestones, and setting vision for the future.',0,0,'news/20.webp',1,'published','2026-10-01 06:33:15','2026-10-01 06:33:15');
