INSERT INTO `galleries_translations` VALUES ('ar',1,'مؤتمر التقنية 2024','مؤتمر تقني سنوي يضم متحدثين رئيسيين وورش عمل وفرص تواصل للمحترفين في القطاع.'),('ar',2,'فعالية إطلاق المنتج','كشف حصري عن أحدث منتجاتنا مع عروض حية وجلسات أسئلة وأجوبة مع فريق التطوير.'),('ar',3,'خلوة بناء الفريق','خلوة على مستوى الشركة تركز على التعاون والابتكار وتعزيز روابط الفريق في بيئة مريحة.'),('ar',4,'قمة الابتكار','قمة لمدة يومين تجمع قادة الفكر لمناقشة التقنيات الناشئة والاتجاهات المستقبلية.'),('ar',5,'لقاء المطورين','تجمع شهري للمطورين لتبادل المعرفة ومناقشة أفضل الممارسات والتعاون في مشاريع المصدر المفتوح.'),('ar',6,'سلسلة ورش الذكاء الاصطناعي','ورش عمل تطبيقية تغطي تعلم الآلة والشبكات العصبية وتطبيقات الذكاء الاصطناعي العملية.'),('ar',7,'عرض الشركات الناشئة','منصة للشركات الناشئة لتقديم حلولها المبتكرة للمستثمرين وخبراء القطاع.'),('ar',8,'ذكرى تأسيس الشركة','احتفال برحلتنا مع الموظفين والشركاء والعملاء الذين ساهموا في نجاحنا.'),('ar',9,'عطلة نهاية الأسبوع للهاكاثون','ماراثون برمجة لمدة 48 ساعة تتنافس فيه الفرق لبناء حلول مبتكرة لمشكلات واقعية.'),('ar',10,'ليلة جوائز الصناعة','حفل سنوي يكرّم التميز والابتكار في التكنولوجيا عبر فئات متعددة.'),('ar',11,'افتتاح المكتب الجديد','افتتاح كبير لمنشأتنا الحديثة المصممة لتعزيز الإبداع والتعاون.'),('ar',12,'مبادرات المجتمع','مبادرات تركز على رد الجميل للمجتمع عبر التعليم وبرامج إتاحة التكنولوجيا.'),('ar',13,'سلسلة أحاديث التقنية','عروض أسبوعية يقدمها خبراء الصناعة حول أحدث التقنيات وأفضل الممارسات.'),('ar',14,'احتفال الشراكة','احتفاء بالشراكات الاستراتيجية التي تدفع الابتكار والنمو المتبادل.'),('ar',15,'مراجعة العام','استعراض سنوي يسلط الضوء على الإنجازات والمحطات الرئيسية ووضع الرؤية للمستقبل.'),('fr',1,'Conférence Tech 2024','Conférence technologique annuelle avec des keynotes, des ateliers et des opportunités de réseautage pour les professionnels du secteur.'),('fr',2,'Événement de lancement produit','Présentation exclusive de notre dernière gamme de produits avec démonstrations en direct et sessions de questions-réponses avec l\'équipe de développement.'),('fr',3,'Retraite de cohésion d\'équipe','Retraite à l\'échelle de l\'entreprise axée sur la collaboration, l\'innovation et le renforcement des liens d\'équipe dans un cadre détendu.'),('fr',4,'Sommet de l\'innovation','Sommet de deux jours réunissant des leaders d\'opinion pour discuter des technologies émergentes et des tendances futures.'),('fr',5,'Rencontre des développeurs','Rencontre mensuelle de développeurs pour partager des connaissances, discuter des bonnes pratiques et collaborer sur des projets open source.'),('fr',6,'Série d\'ateliers IA','Ateliers pratiques couvrant l\'apprentissage automatique, les réseaux de neurones et les applications concrètes de l\'IA.'),('fr',7,'Vitrine des startups','Plateforme permettant aux startups émergentes de présenter leurs solutions innovantes aux investisseurs et aux experts du secteur.'),('fr',8,'Anniversaire de l\'entreprise','Célébration de notre parcours avec les employés, partenaires et clients qui ont rendu notre succès possible.'),('fr',9,'Week-end hackathon','Marathon de programmation de 48 heures où les équipes s\'affrontent pour créer des solutions innovantes à des problèmes réels.'),('fr',10,'Soirée des prix de l\'industrie','Cérémonie annuelle récompensant l\'excellence et l\'innovation technologique dans diverses catégories.'),('fr',11,'Inauguration du nouveau bureau','Inauguration de notre installation ultramoderne conçue pour favoriser la créativité et la collaboration.'),('fr',12,'Actions communautaires','Initiatives visant à redonner à la communauté par l\'éducation et des programmes d\'accès à la technologie.'),('fr',13,'Série Tech Talks','Présentations hebdomadaires d\'experts du secteur sur les technologies de pointe et les bonnes pratiques.'),('fr',14,'Célébration du partenariat','Commémoration de partenariats stratégiques qui stimulent l\'innovation et la croissance mutuelle.'),('fr',15,'Bilan de l\'année','Rétrospective annuelle mettant en avant les réalisations, les jalons et la vision pour l\'avenir.'),('id',1,'Konferensi Teknologi 2024','Konferensi teknologi tahunan dengan pembicara utama, lokakarya, dan peluang jejaring bagi profesional industri.'),('id',2,'Acara peluncuran produk','Peluncuran eksklusif lini produk terbaru kami dengan demo langsung dan sesi tanya jawab bersama tim pengembangan.'),('id',3,'Retret pembentukan tim','Retret tingkat perusahaan yang berfokus pada kolaborasi, inovasi, dan memperkuat ikatan tim dalam suasana santai.'),('id',4,'KTT Inovasi','KTT dua hari yang mempertemukan para pemimpin pemikiran untuk membahas teknologi baru dan tren masa depan.'),('id',5,'Pertemuan pengembang','Pertemuan bulanan para pengembang untuk berbagi pengetahuan, membahas praktik terbaik, dan berkolaborasi pada proyek sumber terbuka.'),('id',6,'Seri lokakarya AI','Lokakarya praktik yang membahas pembelajaran mesin, jaringan saraf, dan aplikasi AI yang nyata.'),('id',7,'Pameran startup','Platform bagi startup baru untuk mempresentasikan solusi inovatif kepada investor dan pakar industri.'),('id',8,'Ulang tahun perusahaan','Merayakan perjalanan kami bersama karyawan, mitra, dan pelanggan yang membuat kesuksesan kami terwujud.'),('id',9,'Akhir pekan hackathon','Maraton coding 48 jam di mana tim bersaing membangun solusi inovatif untuk masalah dunia nyata.'),('id',10,'Malam penghargaan industri','Upacara tahunan yang mengakui keunggulan dan inovasi teknologi dalam berbagai kategori.'),('id',11,'Pembukaan kantor baru','Pembukaan besar fasilitas modern kami yang dirancang untuk mendorong kreativitas dan kolaborasi.'),('id',12,'Program komunitas','Inisiatif yang berfokus pada memberi kembali kepada komunitas melalui pendidikan dan program akses teknologi.'),('id',13,'Seri Tech Talks','Presentasi mingguan oleh pakar industri tentang teknologi mutakhir dan praktik terbaik.'),('id',14,'Perayaan kemitraan','Memperingati kemitraan strategis yang mendorong inovasi dan pertumbuhan bersama.'),('id',15,'Tinjauan akhir tahun','Tinjauan tahunan yang menyoroti pencapaian, tonggak, dan penetapan visi untuk masa depan.'),('tr',1,'Teknoloji Konferansı 2024','Sektör profesyonelleri için açılış konuşmaları, atölyeler ve ağ kurma fırsatları içeren yıllık teknoloji konferansı.'),('tr',2,'Ürün Lansman Etkinliği','En yeni ürün serimizin özel tanıtımı; canlı demolar ve geliştirme ekibiyle soru-cevap oturumları.'),('tr',3,'Takım Oluşturma Kampı','Şirket genelinde düzenlenen, iş birliği, yenilik ve takım bağlarını rahat bir ortamda güçlendirmeye odaklanan kamp.'),('tr',4,'İnovasyon Zirvesi','Gelişen teknolojileri ve gelecekteki eğilimleri tartışmak için düşünce liderlerini bir araya getiren iki günlük zirve.'),('tr',5,'Geliştirici Buluşması','Bilgi paylaşmak, en iyi uygulamaları tartışmak ve açık kaynak projelerinde iş birliği yapmak için geliştiricilerin aylık buluşması.'),('tr',6,'Yapay Zeka Atölye Serisi','Makine öğrenimi, sinir ağları ve pratik AI uygulamalarını kapsayan uygulamalı atölyeler.'),('tr',7,'Startup Vitrini','Yükselen startup\'ların yenilikçi çözümlerini yatırımcılar ve sektör uzmanlarına sunmaları için bir platform.'),('tr',8,'Şirket Yıl Dönümü','Başarımızı mümkün kılan çalışanlar, ortaklar ve müşterilerle yolculuğumuzu kutlama.'),('tr',9,'Hackathon Haftasonu','Takımların gerçek dünya sorunlarına yenilikçi çözümler geliştirmek için yarıştığı 48 saatlik kodlama maratonu.'),('tr',10,'Sektör Ödül Gecesi','Teknoloji alanında çeşitli kategorilerde mükemmeliyet ve inovasyonu ödüllendiren yıllık tören.'),('tr',11,'Yeni Ofis Açılışı','Yaratıcılığı ve iş birliğini teşvik etmek için tasarlanmış son teknoloji tesisimizin büyük açılışı.'),('tr',12,'Topluluk Çalışmaları','Eğitim ve teknolojiye erişim programları yoluyla topluma geri vermeye odaklanan girişimler.'),('tr',13,'Teknoloji Söyleşileri Serisi','Sektör uzmanlarının en yeni teknolojiler ve en iyi uygulamalar hakkında haftalık sunumları.'),('tr',14,'Ortaklık Kutlaması','İnovasyonu ve karşılıklı büyümeyi destekleyen stratejik ortaklıkların anısına düzenlenen kutlama.'),('tr',15,'Yılın Değerlendirmesi','Başarıları ve dönüm noktalarını vurgulayan ve geleceğe yönelik vizyon belirleyen yıllık değerlendirme.'),('vi',1,'Hội nghị Công nghệ 2024','Hội nghị công nghệ thường niên với các bài phát biểu chính, workshop và cơ hội kết nối dành cho chuyên gia trong ngành.'),('vi',2,'Sự kiện ra mắt sản phẩm','Ra mắt độc quyền dòng sản phẩm mới nhất với trình diễn trực tiếp và phiên hỏi đáp cùng đội ngũ phát triển.'),('vi',3,'Chuyến retreat xây dựng đội ngũ','Kỳ retreat toàn công ty tập trung vào hợp tác, đổi mới và gắn kết đội ngũ trong môi trường thư giãn.'),('vi',4,'Hội nghị Thượng đỉnh Đổi mới','Hội nghị kéo dài hai ngày quy tụ các nhà lãnh đạo tư tưởng để thảo luận công nghệ mới nổi và xu hướng tương lai.'),('vi',5,'Gặp gỡ lập trình viên','Buổi gặp gỡ hàng tháng của lập trình viên để chia sẻ kiến thức, thảo luận thực hành tốt và hợp tác trong các dự án mã nguồn mở.'),('vi',6,'Chuỗi workshop AI','Các workshop thực hành về học máy, mạng nơ-ron và các ứng dụng AI thực tiễn.'),('vi',7,'Trình diễn startup','Nền tảng để các startup mới nổi trình bày giải pháp sáng tạo trước nhà đầu tư và chuyên gia ngành.'),('vi',8,'Kỷ niệm công ty','Kỷ niệm hành trình cùng nhân viên, đối tác và khách hàng đã góp phần làm nên thành công.'),('vi',9,'Cuối tuần Hackathon','Marathon lập trình 48 giờ nơi các đội thi đấu xây dựng giải pháp sáng tạo cho các vấn đề thực tế.'),('vi',10,'Đêm trao giải ngành','Lễ trao giải thường niên tôn vinh sự xuất sắc và đổi mới trong công nghệ ở nhiều hạng mục.'),('vi',11,'Khai trương văn phòng mới','Khai trương cơ sở hiện đại của chúng tôi, được thiết kế để thúc đẩy sáng tạo và hợp tác.'),('vi',12,'Hoạt động cộng đồng','Các sáng kiến hướng tới đóng góp cho cộng đồng thông qua giáo dục và chương trình tiếp cận công nghệ.'),('vi',13,'Chuỗi Tech Talks','Các buổi trình bày hàng tuần của chuyên gia ngành về công nghệ tiên tiến và thực hành tốt.'),('vi',14,'Lễ kỷ niệm hợp tác','Kỷ niệm các mối quan hệ hợp tác chiến lược thúc đẩy đổi mới và tăng trưởng cùng có lợi.'),('vi',15,'Tổng kết năm','Tổng kết thường niên nêu bật thành tựu, cột mốc và định hướng tầm nhìn cho tương lai.');
